#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> countSmallerWithOppositeParity(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> ans(n, 0);
        std::vector<int> evenSeen, oddSeen;
        for (int i = n - 1; i >= 0; --i) {
            int val = nums[i];
            if (val % 2 == 0) {
                ans[i] = std::lower_bound(oddSeen.begin(), oddSeen.end(), val) - oddSeen.begin();
                evenSeen.insert(std::lower_bound(evenSeen.begin(), evenSeen.end(), val), val);
            } else {
                ans[i] = std::lower_bound(evenSeen.begin(), evenSeen.end(), val) - evenSeen.begin();
                oddSeen.insert(std::lower_bound(oddSeen.begin(), oddSeen.end(), val), val);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] countSmallerWithOppositeParity(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        List<Integer> evenSeen = new ArrayList<>();
        List<Integer> oddSeen = new ArrayList<>();
        for (int i = n - 1; i >= 0; i--) {
            int val = nums[i];
            if (val % 2 == 0) {
                ans[i] = lowerBound(oddSeen, val);
                int idx = lowerBound(evenSeen, val);
                evenSeen.add(idx, val);
            } else {
                ans[i] = lowerBound(evenSeen, val);
                int idx = lowerBound(oddSeen, val);
                oddSeen.add(idx, val);
            }
        }
        return ans;
    }

    private int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (list.get(mid) >= target) high = mid;
            else low = mid + 1;
        }
        return low;
    }
}

